#include <errno.h>
#include <stddef.h>
#include <unistd.h>

static int write_all(int fd, const unsigned char *bytes, size_t count)
{
    size_t done = 0;
    while (done < count) {
        ssize_t result = write(fd, bytes + done, count - done);
        if (result < 0 && errno == EINTR) {
            continue;
        }
        if (result <= 0) {
            return -1;
        }
        done += (size_t)result;
    }
    return 0;
}

int main(void)
