    unsigned char err[256];
    for (size_t i = 0; i < sizeof(out); ++i) {
        out[i] = (unsigned char)i;
        err[i] = (unsigned char)(255 - i);
    }
    for (unsigned int chunk = 0; chunk < 16; ++chunk) {
